pub open spec fn rmi_version_spec(req: RmiInterfaceVersion, result: Result<(), RmiStatusCode>, lower: RmiInterfaceVersion, higher: RmiInterfaceVersion, old_s: S, new_s: S) -> bool {
    ((!RmiVersionIsSupported(old_s, req) && RmiVersionLowerIsSupported(old_s, req)) ==> (ResultEqual(result, RMI_ERROR_INPUT) && VersionEqualRmi(lower, RmiVersionHighestBelow(old_s, req)) && VersionEqualRmi(higher, RmiVersionHighest(old_s))))
    && ((!RmiVersionIsSupported(old_s, req) && !RmiVersionLowerIsSupported(old_s, req) && RmiVersionHigherIsSupported(old_s, req)) ==> (ResultEqual(result, RMI_ERROR_INPUT) && VersionEqualRmi(lower, RmiVersionHighest(old_s)) && VersionEqualRmi(higher, RmiVersionHighest(old_s))))
    && (RmiVersionIsSupported(old_s, req) ==> (result.is_Ok() && VersionEqualRmi(lower, req) && VersionEqualRmi(higher, RmiVersionHighest(old_s))))
}

pub open spec fn rmi_vsmmu_map_spec(rd: Address, vsmmu_ptr: Address, ipa: Address, level: Int64, result: Result<(), RmiStatusCode>, old_s: S, new_s: S) -> bool {
    let realm = RealmAt(old_s, rd);
    let vsmmu = VsmmuAt(old_s, vsmmu_ptr);
    let walk = RttWalk(old_s, realm, ipa, level as int, RMM_RTT_TREE_PRIMARY);
    let entry_idx = RttEntryIndex(old_s, ipa, walk.level);
    let da = ImplFeatures(old_s).feat_da == FEATURE_TRUE;
    let rd_ok = AddrIsGranuleAligned(old_s, rd) && PaIsDelegable(old_s, rd) && GranuleAt(old_s, rd).state == RD;
    let vsmmu_ok = AddrIsGranuleAligned(old_s, vsmmu_ptr) && PaIsDelegable(old_s, vsmmu_ptr) && GranuleAt(old_s, vsmmu_ptr).state == VSMMU;
    let input_fail = !rd_ok
        || (rd_ok && (!RttLevelIsValid(old_s, realm, level as int) || level < 2 || realm.state != REALM_NEW))
        || (da && !vsmmu_ok)
        || !AddrIsRttLevelAligned(old_s, ipa, level as int)
        || (vsmmu_ok && ipa < vsmmu.reg_base);
    let rtt_fail = rd_ok && (
        walk.level < level as int
        || walk.rtte.state != UNASSIGNED
        || walk.rtte.ripas != EMPTY
        || (vsmmu_ok && (ipa as int) + RttLevelSize(old_s, walk.level) - 1 >= (vsmmu.reg_top as int))
    );
    (!da ==> result.is_Err())
    && (input_fail ==> result.is_Err())
    && (rtt_fail ==> result.is_Err())
    && (result.is_Err() ==> (ResultEqual(result, RMI_ERROR_NOT_SUPPORTED) || ResultEqual(result, RMI_ERROR_INPUT) || ResultEqual(result, RMI_ERROR_RTT(walk.level))))
    && (ResultEqual(result, RMI_ERROR_NOT_SUPPORTED) ==> !da)
    && (ResultEqual(result, RMI_ERROR_INPUT) ==> input_fail)
    && ((result.is_Err() && !ResultEqual(result, RMI_ERROR_NOT_SUPPORTED) && !ResultEqual(result, RMI_ERROR_INPUT)) ==> (rtt_fail && ResultEqual(result, RMI_ERROR_RTT(walk.level))))
    && ((da && !input_fail && !rtt_fail) ==> result.is_Ok())
    && (result.is_Ok() ==> (
        RttEntryAt(new_s, RttAt(new_s, walk.rtt_addr), entry_idx).state == ASSIGNED_VSMMU
        && RttEntryAt(new_s, RttAt(new_s, walk.rtt_addr), entry_idx).addr == vsmmu_ptr
    ))
    && (result.is_Err() ==> RttEntryAt(new_s, RttAt(new_s, walk.rtt_addr), entry_idx) == RttEntryAt(old_s, RttAt(old_s, walk.rtt_addr), entry_idx))
}

pub open spec fn rsi_attestation_token_continue_spec(addr: Address, offset: UInt64, size: UInt64, result: RsiCommandReturnCode, len: UInt64, old_s: S, new_s: S) -> bool {
    let realm = CurrentRealm(old_s);
    let rec = CurrentRec(old_s);
    let walk = RttWalk(old_s, realm, addr, RMM_RTT_PAGE_LEVEL, RMM_RTT_TREE_PRIMARY);
    let input_fail = !AddrIsGranuleAligned(old_s, addr)
        || !AddrIsProtected(old_s, addr, realm)
        || walk.rtte.ripas == EMPTY
        || (offset as int) >= (RMM_GRANULE_SIZE as int)
        || (offset as int) + (size as int) > 0xFFFF_FFFF_FFFF_FFFF
        || (offset as int) + (size as int) > (RMM_GRANULE_SIZE as int);
    let state_fail = rec.attest_state != ATTEST_IN_PROGRESS;
    (input_fail ==> (result == RSI_ERROR_INPUT || (state_fail && result == RSI_ERROR_STATE)))
    && (state_fail ==> (result == RSI_ERROR_STATE || (input_fail && result == RSI_ERROR_INPUT)))
    && ((!input_fail && !state_fail) ==> (
        result == RSI_ERROR_UNKNOWN
        || (
            (result == RSI_SUCCESS || result == RSI_INCOMPLETE)
            && (len as int) == AttestationTokenWrite(old_s, addr, offset as int, size as int)
            && (result == RSI_INCOMPLETE ==> CurrentRec(new_s).attest_state == ATTEST_IN_PROGRESS)
            && (result == RSI_SUCCESS ==> CurrentRec(new_s).attest_state == NO_ATTEST_IN_PROGRESS)
        )
    ))
}

pub open spec fn rsi_vsmmu_activate_spec(base: Address, top: Address, result: RsiCommandReturnCode, new_base: Address, old_s: S, new_s: S) -> bool {
    let old_realm = CurrentRealm(old_s);
    let old_walk = RttWalk(old_s, old_realm, base, RMM_RTT_PAGE_LEVEL, RMM_RTT_TREE_PRIMARY);
    let realm = CurrentRealm(new_s);
    let walk = RttWalk(new_s, realm, base, RMM_RTT_PAGE_LEVEL, RMM_RTT_TREE_PRIMARY);
    let vsmmu = VsmmuAt(new_s, walk.rtte.addr);
    (!AddrIsGranuleAligned(old_s, base) ==> result == RSI_ERROR_INPUT)
    && (!AddrIsGranuleAligned(old_s, top) ==> result == RSI_ERROR_INPUT)
    && (top <= base ==> result == RSI_ERROR_INPUT)
    && (!AddrRangeIsProtected(old_s, base, top, old_realm) ==> result == RSI_ERROR_INPUT)
    && (old_walk.rtte.state != ASSIGNED_VSMMU ==> result == RSI_ERROR_INPUT)
    && ((AddrIsGranuleAligned(old_s, base)
        && AddrIsGranuleAligned(old_s, top)
        && top > base
        && AddrRangeIsProtected(old_s, base, top, old_realm)
        && old_walk.rtte.state == ASSIGNED_VSMMU)
        ==> (result == RSI_SUCCESS
            && RttEntriesInRangeRipas(new_s, RttAt(new_s, walk.rtt_addr), walk.level, base, new_base, DEV)
            && ((base == vsmmu.reg_base && new_base != vsmmu.reg_top) ==> vsmmu.state == VSMMU_ACTIVATING)
            && (new_base == vsmmu.reg_top ==> vsmmu.state == VSMMU_ACTIVE)))
}
